// HasChargeType applies the HasEdge predicate on the "charge_type" edge.
func HasChargeType() predicate.ChargeRate {
	return predicate.ChargeRate(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ChargeTypeTable, ChargeTypeColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasChargeTypeWith applies the HasEdge predicate on the "charge_type" edge with a given conditions (other predicates).
func HasChargeTypeWith(preds ...predicate.ChargeType) predicate.ChargeRate {
	return predicate.ChargeRate(func(s *sql.Selector) {
		step := newChargeTypeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

